{
  "actions": [
    {
      "title": "Make API Call",
      "description": "Performs an arbitrary authorized API call to a Figma endpoint by specifying the resource, HTTP method, and any necessary request body. It can be used for custom operations that are not explicitly defined as a discrete action.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api",
      "endpointUrl": "https://api.figma.com/v1/{resource}",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "POST",
      "sampleResponse": {},
      "inputSchema": {
        "type": "object",
        "properties": {
          "resource": {
            "type": "string",
            "description": "The resource path to call, for example 'files/{file_id}' or 'teams/{team_id}/projects'."
          },
          "method": {
            "type": "string",
            "description": "HTTP method to use for the call (GET, POST, PUT, PATCH, DELETE)."
          },
          "body": {
            "type": "object",
            "description": "Optional request body to include in the API call if applicable."
          }
        }
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Post Comment",
      "description": "Posts a comment to a specified Figma file.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api#comments-post",
      "endpointUrl": "https://api.figma.com/v1/files/{file_id}/comments",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "POST",
      "sampleResponse": {
        "id": "c1",
        "message": "This is a comment",
        "created_at": "2020-01-01T00:00:00Z"
      },
      "inputSchema": {
        "type": "object",
        "properties": {
          "file_id": {
            "type": "string",
            "description": "The unique identifier of the Figma file where the comment should be posted."
          },
          "message": {
            "type": "string",
            "description": "The text content of the comment to be posted."
          }
        }
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Find Comments",
      "description": "Fetches all comments for a given Figma file, with support for an optional search query filter.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api#comments-get",
      "endpointUrl": "https://api.figma.com/v1/files/{file_id}/comments",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "GET",
      "sampleResponse": {
        "comments": [
          {
            "id": "c1",
            "message": "Sample comment",
            "user": {
              "handle": "user1"
            }
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "properties": {
          "file_id": {
            "type": "string",
            "description": "The unique identifier of the Figma file whose comments are to be retrieved."
          },
          "query": {
            "type": "string",
            "description": "Optional search term to filter comments.",
            "default": ""
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "comments",
        "arrayPropertyValue": "comments"
      }
    },
    {
      "title": "Find File Version History",
      "description": "Retrieves the version history of a specified Figma file.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api#file-versions-get",
      "endpointUrl": "https://api.figma.com/v1/files/{file_id}/versions",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "GET",
      "sampleResponse": {
        "versions": [
          {
            "id": "v1",
            "created_at": "2020-01-01T00:00:00Z"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "properties": {
          "file_id": {
            "type": "string",
            "description": "The unique identifier of the Figma file whose version history is being requested."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "versions",
        "arrayPropertyValue": "versions"
      }
    },
    {
      "title": "Find Project Files",
      "description": "Retrieves all files within a specified Figma project.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api#project-files-get",
      "endpointUrl": "https://api.figma.com/v1/projects/{project_id}/files",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "GET",
      "sampleResponse": {
        "files": [
          {
            "key": "fileKey1",
            "name": "File Name 1"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "properties": {
          "project_id": {
            "type": "string",
            "description": "The unique identifier of the Figma project from which files are to be retrieved."
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "files",
        "arrayPropertyValue": "files"
      }
    },
    {
      "title": "Find Projects",
      "description": "Retrieves all projects within a specified Figma team, with an optional search query filter.",
      "type": "action",
      "documentation": "https://www.figma.com/developers/api#projects-get",
      "endpointUrl": "https://api.figma.com/v1/teams/{team_id}/projects",
      "apiBaseUrl": "https://api.figma.com/v1",
      "method": "GET",
      "sampleResponse": {
        "projects": [
          {
            "id": "proj1",
            "name": "Project One"
          }
        ]
      },
      "inputSchema": {
        "type": "object",
        "properties": {
          "team_id": {
            "type": "string",
            "description": "The unique identifier of the Figma team whose projects are to be retrieved."
          },
          "query": {
            "type": "string",
            "description": "Optional search term to filter projects.",
            "default": ""
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "projects",
        "arrayPropertyValue": "projects"
      }
    }
  ],
  "authentication": {
    "type": "oauth2",
    "authUrl": "https://www.figma.com/oauth",
    "tokenUrl": "https://www.figma.com/api/oauth/token",
    "profileInfoUrl": "https://www.figma.com/api/me"
  },
  "serviceJson": {
    "name": "appmixer.figma",
    "label": "Figma",
    "category": "applications",
    "description": "Integration component for Figma, providing endpoints for core operations such as posting comments, retrieving comments, file version history, project files, and team projects.",
    "version": "1.0.0",
    "icon": "https://upload.wikimedia.org/wikipedia/commons/3/33/Figma-logo.svg"
  }
}
